#!/usr/bin/env python3
import os
import time

BASE = "/workspace/notebooks/llama.cpp-ph2/ggml/src/ggml-cuda8"
BACKEND_CPP = os.path.join(BASE, "ggml-cuda8-ggml-backend.cpp")
SMOKE_CPP = os.path.join(BASE, "ggml-cuda8-ggml-backend-graph-compute-add-mul-smoke.cpp")
CMAKE = os.path.join(BASE, "CMakeLists.txt")
BACKEND_CPP_TEXT = '// ggml/src/ggml-cuda8/ggml-cuda8-ggml-backend.cpp\n// G15B: minimal CUDA8 ggml_backend_t backend with tiny real graph_compute support.\n// Supports synthetic/manual graph nodes:\n//   GGML_OP_ADD F32 -> GGML_CUDA8_OP_ADD_F32\n//   GGML_OP_MUL F32 with scalar src1 -> GGML_CUDA8_OP_MUL_SCALAR_F32\n\n#include "ggml-cuda8-ggml-backend.h"\n#include "ggml-cuda8-ggml-buffer.h"\n#include "ggml-cuda8-dispatch.h"\n\n#include "ggml.h"\n#include "ggml-impl.h"\n#include "ggml-backend-impl.h"\n\n#include <cstdio>\n#include <cstdlib>\n#include <cstring>\n\nstruct ggml_cuda8_ggml_backend_context {\n    int device;\n};\n\nstatic const char * cuda8_backend_get_name(ggml_backend_t backend) {\n    (void) backend;\n    return "CUDA8";\n}\n\nstatic void cuda8_backend_free(ggml_backend_t backend) {\n    if (backend == NULL) return;\n    ggml_cuda8_ggml_backend_context * ctx = (ggml_cuda8_ggml_backend_context *) backend->context;\n    if (ctx != NULL) std::free(ctx);\n    std::free(backend);\n}\n\nstatic void cuda8_backend_synchronize(ggml_backend_t backend) {\n    (void) backend;\n    std::printf("ggml-cuda8/backend: synchronize PASS\\n");\n}\n\nstatic ggml_backend_graph_plan_t cuda8_backend_graph_plan_create(ggml_backend_t backend, const struct ggml_cgraph * cgraph) {\n    (void) backend;\n    (void) cgraph;\n    std::printf("ggml-cuda8/backend: graph_plan_create stub PASS\\n");\n    return NULL;\n}\n\nstatic void cuda8_backend_graph_plan_free(ggml_backend_t backend, ggml_backend_graph_plan_t plan) {\n    (void) backend;\n    (void) plan;\n    std::printf("ggml-cuda8/backend: graph_plan_free stub PASS\\n");\n}\n\nstatic void cuda8_backend_graph_plan_update(ggml_backend_t backend, ggml_backend_graph_plan_t plan, const struct ggml_cgraph * cgraph) {\n    (void) backend;\n    (void) plan;\n    (void) cgraph;\n    std::printf("ggml-cuda8/backend: graph_plan_update stub PASS\\n");\n}\n\nstatic enum ggml_status cuda8_backend_graph_plan_compute(ggml_backend_t backend, ggml_backend_graph_plan_t plan) {\n    (void) backend;\n    (void) plan;\n    std::printf("ggml-cuda8/backend: graph_plan_compute stub PASS\\n");\n    return GGML_STATUS_SUCCESS;\n}\n\nstatic int64_t tensor_nelements_4d(const struct ggml_tensor * t) {\n    return t->ne[0] * t->ne[1] * t->ne[2] * t->ne[3];\n}\n\nstatic enum ggml_status cuda8_backend_graph_compute(ggml_backend_t backend, struct ggml_cgraph * cgraph) {\n    if (!ggml_cuda8_ggml_backend_is_cuda8(backend)) {\n        std::fprintf(stderr, "ggml-cuda8/backend graph_compute: invalid backend\\n");\n        return (enum ggml_status) -1;\n    }\n\n    if (cgraph == NULL) {\n        std::printf("ggml-cuda8/backend: graph_compute NULL-graph stub PASS\\n");\n        return GGML_STATUS_SUCCESS;\n    }\n\n    ggml_cuda8_context * ctx = NULL;\n    if (ggml_cuda8_context_create(0, &ctx) != 0 || ctx == NULL) {\n        std::fprintf(stderr, "ggml-cuda8/backend graph_compute: failed to create CUDA8 context\\n");\n        return (enum ggml_status) -1;\n    }\n\n    std::printf("ggml-cuda8/backend: graph_compute starting n_nodes=%d\\n", cgraph->n_nodes);\n\n    for (int i = 0; i < cgraph->n_nodes; ++i) {\n        struct ggml_tensor * node = cgraph->nodes[i];\n        if (node == NULL || node->op == GGML_OP_NONE) continue;\n\n        if (node->type != GGML_TYPE_F32 || node->src[0] == NULL || node->src[1] == NULL ||\n            node->src[0]->type != GGML_TYPE_F32 || node->src[1]->type != GGML_TYPE_F32) {\n            std::fprintf(stderr, "ggml-cuda8/backend graph_compute: node %d has unsupported types/sources op=%d\\n", i, (int) node->op);\n            ggml_cuda8_context_destroy(ctx);\n            return (enum ggml_status) -1;\n        }\n\n        int cuda8_op = -1;\n        const char * opname = "UNKNOWN";\n\n        if (node->op == GGML_OP_ADD) {\n            cuda8_op = GGML_CUDA8_OP_ADD_F32;\n            opname = "ADD_F32";\n        } else if (node->op == GGML_OP_MUL && tensor_nelements_4d(node->src[1]) == 1) {\n            cuda8_op = GGML_CUDA8_OP_MUL_SCALAR_F32;\n            opname = "MUL_SCALAR_F32";\n        } else {\n            std::fprintf(stderr, "ggml-cuda8/backend graph_compute: unsupported node %d op=%d\\n", i, (int) node->op);\n            ggml_cuda8_context_destroy(ctx);\n            return (enum ggml_status) -1;\n        }\n\n        std::printf("ggml-cuda8/backend: graph_compute node %d %s\\n", i, opname);\n\n        if (ggml_cuda8_ggml_backend_dispatch_op(backend, ctx, cuda8_op, node->src[0], node->src[1], node) != 0) {\n            std::fprintf(stderr, "ggml-cuda8/backend graph_compute: dispatch failed at node %d op=%s\\n", i, opname);\n            ggml_cuda8_context_destroy(ctx);\n            return (enum ggml_status) -1;\n        }\n    }\n\n    ggml_cuda8_context_destroy(ctx);\n    std::printf("ggml-cuda8/backend: graph_compute SUCCESS\\n");\n    return GGML_STATUS_SUCCESS;\n}\n\nstatic void cuda8_backend_graph_optimize(ggml_backend_t backend, struct ggml_cgraph * cgraph) {\n    (void) backend;\n    (void) cgraph;\n    std::printf("ggml-cuda8/backend: graph_optimize stub PASS\\n");\n}\n\nstatic struct ggml_backend_i cuda8_backend_i;\nstatic bool cuda8_backend_i_initialized = false;\n\nstatic void cuda8_backend_iface_init(void) {\n    if (cuda8_backend_i_initialized) return;\n    std::memset(&cuda8_backend_i, 0, sizeof(cuda8_backend_i));\n\n    cuda8_backend_i.get_name = cuda8_backend_get_name;\n    cuda8_backend_i.free = cuda8_backend_free;\n    cuda8_backend_i.synchronize = cuda8_backend_synchronize;\n    cuda8_backend_i.graph_plan_create = cuda8_backend_graph_plan_create;\n    cuda8_backend_i.graph_plan_free = cuda8_backend_graph_plan_free;\n    cuda8_backend_i.graph_plan_update = cuda8_backend_graph_plan_update;\n    cuda8_backend_i.graph_plan_compute = cuda8_backend_graph_plan_compute;\n    cuda8_backend_i.graph_compute = cuda8_backend_graph_compute;\n    cuda8_backend_i.graph_optimize = cuda8_backend_graph_optimize;\n\n    cuda8_backend_i_initialized = true;\n}\n\nextern "C" ggml_backend_t ggml_cuda8_ggml_backend_init(int device) {\n    cuda8_backend_iface_init();\n\n    ggml_cuda8_ggml_backend_context * ctx =\n        (ggml_cuda8_ggml_backend_context *) std::malloc(sizeof(ggml_cuda8_ggml_backend_context));\n    if (ctx == NULL) return NULL;\n    ctx->device = device;\n\n    ggml_backend_t backend = (ggml_backend_t) std::malloc(sizeof(struct ggml_backend));\n    if (backend == NULL) {\n        std::free(ctx);\n        return NULL;\n    }\n\n    std::memset(backend, 0, sizeof(*backend));\n    backend->iface = cuda8_backend_i;\n    backend->context = ctx;\n    return backend;\n}\n\nextern "C" int ggml_cuda8_ggml_backend_is_cuda8(ggml_backend_t backend) {\n    if (backend == NULL || backend->iface.get_name == NULL) return 0;\n    const char * name = backend->iface.get_name(backend);\n    return name != NULL && std::strcmp(name, "CUDA8") == 0;\n}\n\nextern "C" ggml_backend_buffer_type_t ggml_cuda8_ggml_backend_get_default_buffer_type(ggml_backend_t backend) {\n    if (!ggml_cuda8_ggml_backend_is_cuda8(backend)) return NULL;\n    return ggml_cuda8_ggml_buffer_type();\n}\n\nextern "C" int ggml_cuda8_ggml_backend_dispatch_op(\n    ggml_backend_t backend,\n    ggml_cuda8_context * ctx,\n    int op,\n    const ggml_tensor * src0,\n    const ggml_tensor * src1,\n    ggml_tensor * dst\n) {\n    if (!ggml_cuda8_ggml_backend_is_cuda8(backend)) {\n        std::fprintf(stderr, "ggml-cuda8/backend-dispatch: invalid backend\\n");\n        return -1;\n    }\n    if (ctx == NULL) {\n        std::fprintf(stderr, "ggml-cuda8/backend-dispatch: NULL CUDA8 context\\n");\n        return -1;\n    }\n    if (!ggml_cuda8_dispatch_supported(ctx, op, src0, src1, dst)) {\n        std::fprintf(stderr, "ggml-cuda8/backend-dispatch: unsupported op/layout op=%d\\n", op);\n        return -1;\n    }\n    return ggml_cuda8_dispatch_execute(ctx, op, src0, src1, dst);\n}\n'
SMOKE_TEXT = '// ggml/src/ggml-cuda8/ggml-cuda8-ggml-backend-graph-compute-add-mul-smoke.cpp\n//\n// G15B smoke: real backend->iface.graph_compute dispatch of a two-node graph:\n//   C = A + B\n//   D = C * scalar\n\n#include "ggml-cuda8-ggml-backend.h"\n#include "ggml-cuda8-ggml-buffer.h"\n\n#include "ggml.h"\n#include "ggml-impl.h"\n#include "ggml-backend.h"\n#include "ggml-backend-impl.h"\n\n#include <cstdio>\n#include <cstdlib>\n#include <cstring>\n#include <stdint.h>\n#include <vector>\n\nstatic void setup_f32_vector(ggml_tensor & t, int64_t n, void * data) {\n    std::memset(&t, 0, sizeof(t));\n    t.type = GGML_TYPE_F32;\n    t.ne[0] = n;\n    t.ne[1] = 1;\n    t.ne[2] = 1;\n    t.ne[3] = 1;\n    t.nb[0] = sizeof(float);\n    t.nb[1] = (size_t) n * sizeof(float);\n    t.nb[2] = t.nb[1];\n    t.nb[3] = t.nb[1];\n    t.data = data;\n}\n\nstatic void setup_f32_scalar(ggml_tensor & t, void * data) {\n    setup_f32_vector(t, 1, data);\n}\n\nstatic bool expect_resident(const char * label, const ggml_tensor * t, size_t bytes, ggml_backend_buffer_t expected, size_t expected_offset) {\n    ggml_backend_buffer_t owner = NULL;\n    size_t offset = 0;\n    if (!ggml_cuda8_ggml_tensor_is_device_resident(t, bytes, &owner, &offset)) {\n        std::fprintf(stderr, "%s: residency not found\\n", label);\n        return false;\n    }\n    if (owner != expected || offset != expected_offset) {\n        std::fprintf(stderr, "%s: residency mismatch offset=%zu expected=%zu\\n", label, offset, expected_offset);\n        return false;\n    }\n    std::printf("%s residency PASS offset=%zu\\n", label, offset);\n    return true;\n}\n\nint main(int argc, char ** argv) {\n    (void) argc;\n    (void) argv;\n\n    std::printf("ggml-cuda8-ggml-backend-graph-compute-add-mul-smoke: starting\\n");\n\n    ggml_backend_t backend = ggml_cuda8_ggml_backend_init(0);\n    if (backend == NULL) { std::fprintf(stderr, "backend init failed\\n"); return 1; }\n    if (!ggml_cuda8_ggml_backend_is_cuda8(backend)) { std::fprintf(stderr, "backend identity check failed\\n"); backend->iface.free(backend); return 1; }\n    if (backend->iface.graph_compute == NULL) { std::fprintf(stderr, "backend graph_compute callback is NULL\\n"); backend->iface.free(backend); return 1; }\n\n    std::printf("backend name: %s\\n", backend->iface.get_name(backend));\n\n    ggml_backend_buffer_type_t buft = ggml_cuda8_ggml_backend_get_default_buffer_type(backend);\n    if (buft == NULL) { std::fprintf(stderr, "backend default buffer type is NULL\\n"); backend->iface.free(backend); return 1; }\n    std::printf("backend default buffer type: %s\\n", buft->iface.get_name(buft));\n\n    const int n = 512;\n    const size_t bytes = (size_t) n * sizeof(float);\n    const size_t off_a = 0;\n    const size_t off_b = 4096;\n    const size_t off_c = 8192;\n    const size_t off_d = 12288;\n    const size_t off_scalar = 16384;\n    const size_t total_size = 16640;\n\n    ggml_backend_buffer_t buffer = buft->iface.alloc_buffer(buft, total_size);\n    if (buffer == NULL) { std::fprintf(stderr, "buffer alloc failed\\n"); backend->iface.free(backend); return 1; }\n    void * base = buffer->iface.get_base(buffer);\n    if (base == NULL) { std::fprintf(stderr, "buffer base is NULL\\n"); buffer->iface.free_buffer(buffer); backend->iface.free(backend); return 1; }\n\n    std::printf("backend-owned graph buffer size: %zu\\n", buffer->size);\n    std::printf("buffer base:                     %p\\n", base);\n\n    uint8_t * base_u8 = (uint8_t *) base;\n\n    ggml_tensor a, b, c, d, scalar;\n    setup_f32_vector(a, n, base_u8 + off_a);\n    setup_f32_vector(b, n, base_u8 + off_b);\n    setup_f32_vector(c, n, base_u8 + off_c);\n    setup_f32_vector(d, n, base_u8 + off_d);\n    setup_f32_scalar(scalar, base_u8 + off_scalar);\n\n    c.op = GGML_OP_ADD;\n    c.src[0] = &a;\n    c.src[1] = &b;\n\n    d.op = GGML_OP_MUL;\n    d.src[0] = &c;\n    d.src[1] = &scalar;\n\n    if (buffer->iface.init_tensor(buffer, &a) != GGML_STATUS_SUCCESS ||\n        buffer->iface.init_tensor(buffer, &b) != GGML_STATUS_SUCCESS ||\n        buffer->iface.init_tensor(buffer, &c) != GGML_STATUS_SUCCESS ||\n        buffer->iface.init_tensor(buffer, &d) != GGML_STATUS_SUCCESS ||\n        buffer->iface.init_tensor(buffer, &scalar) != GGML_STATUS_SUCCESS) {\n        std::fprintf(stderr, "init_tensor failed\\n");\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    if (!expect_resident("A", &a, bytes, buffer, off_a) ||\n        !expect_resident("B", &b, bytes, buffer, off_b) ||\n        !expect_resident("C", &c, bytes, buffer, off_c) ||\n        !expect_resident("D", &d, bytes, buffer, off_d) ||\n        !expect_resident("scalar", &scalar, sizeof(float), buffer, off_scalar)) {\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    std::vector<float> a_host(n), b_host(n), d_ref(n), d_out(n, 0.0f);\n    const float scale = -1.5f;\n    for (int i = 0; i < n; ++i) {\n        a_host[i] = ((float) ((i * 17 + 3) % 101) - 50.0f) * 0.03125f;\n        b_host[i] = ((float) ((i * 19 + 5) % 97) - 48.0f) * 0.015625f;\n        d_ref[i] = (a_host[i] + b_host[i]) * scale;\n    }\n\n    buffer->iface.clear(buffer, 0);\n    buffer->iface.set_tensor(buffer, &a, &a_host[0], 0, bytes);\n    buffer->iface.set_tensor(buffer, &b, &b_host[0], 0, bytes);\n    buffer->iface.set_tensor(buffer, &scalar, &scale, 0, sizeof(float));\n\n    ggml_tensor * nodes[2];\n    nodes[0] = &c;\n    nodes[1] = &d;\n\n    ggml_cgraph graph;\n    std::memset(&graph, 0, sizeof(graph));\n    graph.n_nodes = 2;\n    graph.nodes = nodes;\n\n    std::printf("synthetic graph n_nodes=%d\\n", graph.n_nodes);\n    for (int i = 0; i < graph.n_nodes; ++i) {\n        std::printf("graph node %d op=%d\\n", i, (int) graph.nodes[i]->op);\n    }\n\n    enum ggml_status status = backend->iface.graph_compute(backend, &graph);\n    if (status != GGML_STATUS_SUCCESS) {\n        std::fprintf(stderr, "backend graph_compute returned %d\\n", (int) status);\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    buffer->iface.get_tensor(buffer, &d, &d_out[0], 0, bytes);\n\n    double max_abs_err = 0.0;\n    for (int i = 0; i < n; ++i) {\n        const double diff = (double) d_out[i] - (double) d_ref[i];\n        const double abs_err = diff < 0.0 ? -diff : diff;\n        if (abs_err > max_abs_err) max_abs_err = abs_err;\n    }\n\n    std::printf("graph_compute ADD->MUL_SCALAR max_abs_err=%.9g\\n", max_abs_err);\n    if (max_abs_err > 1e-6) {\n        std::fprintf(stderr, "graph_compute ADD->MUL_SCALAR verification FAIL\\n");\n        buffer->iface.free_buffer(buffer);\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    std::printf("graph_compute ADD->MUL_SCALAR verification PASS\\n");\n\n    buffer->iface.free_buffer(buffer);\n    backend->iface.free(backend);\n\n    std::printf("ggml-cuda8-ggml-backend-graph-compute-add-mul-smoke: SUCCESS\\n");\n    return 0;\n}\n'
CMAKE_TARGET = '\n# ---------------------------------------------------------------------------\n# G15B real backend->iface.graph_compute ADD -> MUL_SCALAR smoke\n# ---------------------------------------------------------------------------\n\ncuda_add_executable(ggml-cuda8-ggml-backend-graph-compute-add-mul-smoke\n    ggml-cuda8-ggml-backend-graph-compute-add-mul-smoke.cpp\n)\n\ntarget_link_libraries(ggml-cuda8-ggml-backend-graph-compute-add-mul-smoke\n    ggml-cuda8-kernels\n    ${CUDA_LIBRARIES}\n)\n'

def backup(path):
    if os.path.exists(path):
        b = path + ".g15b-backup-" + str(int(time.time()))
        with open(path, "r") as f:
            data = f.read()
        with open(b, "w") as f:
            f.write(data)
        print("backup", b)

def write(path, text):
    backup(path)
    with open(path, "w") as f:
        f.write(text)
    print("wrote", path)

write(BACKEND_CPP, BACKEND_CPP_TEXT)
write(SMOKE_CPP, SMOKE_TEXT)
backup(CMAKE)
with open(CMAKE, "r") as f:
    cm = f.read()
if "ggml-cuda8-ggml-backend-graph-compute-add-mul-smoke" not in cm:
    if not cm.endswith("\n"):
        cm += "\n"
    cm += CMAKE_TARGET
    with open(CMAKE, "w") as f:
        f.write(cm)
    print("patched", CMAKE)
else:
    print("CMake target already present")
print("")
print("G15B writer complete.")
